  "vidcfg.durationAutoHint": "자동: 모델이 길이를 정합니다(레퍼런스 동영상을 편집할 때는 원본 클립의 길이). 크레딧은 가장 긴 클립 기준으로 예약되며, 실제 출력된 길이에 맞춰 차액이 환불됩니다.",
  "vidcfg.wan3Note": "요금은 길이와 해상도에 따라 정해지며, 실행 버튼에 선택한 길이의 요금이 표시됩니다. 클립과 함께 주변음이 생성됩니다. “적응형”은 연결된 입력에 맞춰지며, 텍스트만으로 동영상을 만들 때는 특정 비율을 선택하지 않으면 16:9로 렌더링됩니다.",
  "vidcfg.wan3VideoRefLimits": "Wan 3.0에서는 각 원본 클립이 1~15초, 연결된 클립의 합계가 15초 이하, 입력 길이와 출력 길이의 합이 30초 이하여야 합니다. 이 조건은 작업을 제출하기 전이 아니라 작업이 실행될 때 공급자가 확인합니다.",
  "vidcfg.wan3AudioRefLimits": "각 레퍼런스 오디오는 1~15초여야 하며(작업 제출 전에 확인), 연결된 모든 오디오의 합계는 15초 이하여야 합니다.",
