  "vidcfg.sameSeedSimilar": "같은 시드를 사용하면 비슷한 결과가 나옵니다. 무작위로 하려면 비워 두세요.",
  "vidcfg.veo31Audio": "VEO 3.1은 프롬프트로 AI 오디오를 생성합니다. 무음 동영상을 만들려면 끄고, “동영상 및 오디오 병합” 노드를 사용하세요.",
  "vidcfg.veoAutoTranslateNote": "프롬프트는 VEO에 전달되기 전에 영어로 자동 번역됩니다(기본적으로 켜짐). 프롬프트를 그대로 유지하려면 끄세요. 영어가 아닌 프롬프트나 정확한 문구가 중요한 경우(예: 퍼펙트 루프 고정 문구)에 유용합니다.",
  "vidcfg.veoAutoTranslateNoteShort": "프롬프트는 VEO에 전달되기 전에 영어로 자동 번역됩니다(기본적으로 켜짐). 프롬프트를 그대로 유지하려면 끄세요.",
  "vidcfg.worksBestSameFrames": "시작 프레임과 종료 프레임을 같은 이미지로 고정하면 가장 잘 작동합니다. 종료 프레임이 없으면 알고리즘이 찾을 수 있는 최적의 루프 지점을 선택하지만, 결과가 매끄럽게 이어지지 않을 수 있습니다.",
  "vidcfg.splitsScript": "대본을 세그먼트별 프롬프트로 나눕니다. 기본값: Claude Opus 4.7.",
