  "audiocfg.descTalkingHeadFaceEnh": "토킹 헤드 동영상과 오디오 트랙을 연결하세요. 얼굴 보정 기능이 내장되어 있습니다.",
  "audiocfg.descPortraitTalkingHead": "인물 사진과 오디오 트랙(음성)을 연결하면 토킹 헤드 동영상을 생성합니다.",
  "audiocfg.descSingingDiffusion": "동영상과 오디오 트랙을 연결하세요. 노래에 가장 적합하며, 확산 모델로 고품질 립싱크를 수행합니다.",
  "audiocfg.descFastCheapLipSync": "동영상 또는 이미지와 오디오 트랙을 연결하세요. 빠르고 저렴한 립싱크입니다.",
  "audiocfg.descPortraitNaturalMotion": "인물 사진과 오디오를 연결하면 자연스럽게 움직이는 토킹 헤드를 생성합니다.",
  "audiocfg.descAvatarInference": "동영상과 오디오 트랙을 연결하면 고정밀 아바타 추론 립싱크로 음성을 교체하거나 더빙합니다. 출력 1초 단위로 요금이 청구됩니다.",
  "audiocfg.descStudioGrade": "스튜디오급 립싱크를 하려면 동영상(.mp4)과 오디오 트랙(.wav)을 연결하세요. 출력 1초 단위로 요금이 청구됩니다.",
  "audiocfg.descSyncSo": "동영상과 오디오 트랙을 연결하면 sync.so v3(fal.ai) 모델로 영상을 더빙합니다. 출력 1초 단위로 요금이 청구됩니다.",
  "audiocfg.descVolcengine": "동영상과 오디오 트랙을 연결하면 영상을 더빙합니다(Volcengine). 출력 길이는 오디오를 따릅니다. 1초 단위로 요금이 청구되며, 초당 약 2크레딧입니다.",
  "audiocfg.descVoiceExtractor": "모든 오디오 입력에서 배경 소음을 제거하고 깨끗한 음성을 추출합니다. 오디오 소스(“오디오 업로드”, “텍스트 음성 변환” 등)를 입력에 연결하세요.",
  "audiocfg.hintSpeakerBoostDesc": "원본의 말투를 증폭합니다. 더 극적인 표현을 원하는 경우가 아니면 0으로 두세요. 값이 높을수록 지연 시간이 늘고 안정성이 떨어질 수 있습니다.",
  "audiocfg.hintSimilarityBoostDesc": "대상 보이스와의 유사도를 높입니다(연산량이 늘고 지연 시간이 약간 생김). 기본적으로 켜져 있습니다.",
  "audiocfg.hintSeedReproducible": "값을 고정하면 같은 출력을 재현할 수 있습니다(같은 시드 + 같은 입력 + 같은 설정). 무작위로 하려면 비워 두세요.",
  "audiocfg.hintDubCloneDesc": "기본적으로 더빙은 원래 화자의 목소리를 복제합니다. 즉, 화자가 자신의 목소리와 억양 그대로 대상 언어를 말합니다. 대신 비슷한 원어민 느낌의 목소리를 사용하려면 이 옵션을 선택하세요.",
  "audiocfg.hintDubTranslate": "음성을 대상 언어로 번역합니다. 오디오 소스를 입력에 연결하세요.",
  "audiocfg.descVoiceDesign": "자연어 설명으로 새 보이스를 생성하고, 지정한 텍스트로 오디오 미리 듣기를 만듭니다.",
  "audiocfg.descForcedAlign": "오디오를 녹취록과 정렬해 단어 단위 타임스탬프를 생성합니다. 오디오 소스를 입력에 연결하세요.",
  "audiocfg.descRecast": "화자는 자동으로 감지됩니다. 보이스 1은 처음 말하는 화자의 목소리를, 보이스 2는 두 번째로 말하는 화자의 목소리를 바꾸며, 이후도 같은 방식입니다. 목록의 보이스 수를 넘는 화자는 원래 목소리를 유지합니다.",
  "audiocfg.hintPreservedMusicLevel": "바뀐 목소리 대비 유지되는 배경 음악의 음량을 설정합니다.",
  "audiocfg.hintRevoiceOffOn": "꺼짐: 새 목소리 아래에 깔린 배경 음악/효과음을 유지합니다. 켜짐: 목소리만 남긴 깨끗한 출력입니다.",
  "audiocfg.hintRevoicePre": "감정, 억양, 타이밍은 유지하면서 목소리를 선택한 보이스로 바꿉니다. “",
  "audiocfg.hintRevoiceMid": "”를 연결하면 오디오가 출력되고, “",
  "audiocfg.hintRevoicePost": "”을 연결하면 말하는 클립 전체의 목소리를 바꿀 수 있습니다(동영상과 새 오디오 트랙이 함께 반환됩니다). 둘 다 연결하면 동영상이 우선하며 오디오 입력은 무시됩니다.",
  "audiocfg.similarity": "유사도",
