  "audiocfg.silencePaddingHint": "음성 앞뒤에 남겨 두는 여유분입니다. 각 무음 구간이 이 값만큼 안쪽으로 줄어듭니다.",
  "audiocfg.silenceRangeCount": "무음 구간 {count}개",
  "audiocfg.audioSyncHint": "녹음들의 소리를 비교해 시계가 서로 얼마나 어긋나 있는지 측정합니다. 각 오프셋은 해당 녹음을 기준 녹음의 시계에 맞추려면 얼마나 이동해야 하는지를 나타냅니다. 시계 드리프트는 보고만 되며 보정되지 않습니다.",
