  "tut.mrcHint1": "1에서 인물을, 5에서 장소를 가져오고, 가져오지 말아야 할 것도 명시합니다. 무엇을 가져오지 않을지 말하는 것은 무엇을 가져올지 말하는 것만큼 중요합니다.",
  "tut.mrcHint2": "2에서 오브젝트를 가져오고, 5개 소스 어디에도 없는 지시를 더합니다.",
  "tut.mrcHint3": "3에서 디테일을 가져오되 얼굴 한쪽으로만 제한합니다. 반대쪽 뺨은 비어 있다고 명시합니다.",
  "tut.mrcHint4": "4에서 옷 전체를 가져와 그대로 정확히 재현합니다.",
  "tut.mrcHint5": "속성 하나만 가져옵니다. 5에서 빌려 오는 것은 셔츠 자체가 아니라 셔츠의 색상입니다.",
  "tut.mrcAddRefsTitle": "레퍼런스 추가",
  "tut.mrcAddRefsSub": "순서가 토큰 번호를 정합니다",
  "tut.mrcWritePromptTitle": "프롬프트 작성",
  "tut.mrcWritePromptSub": "토큰에 마우스를 올리면 무엇을 가져오는지 보입니다",
  "tut.mrcGenerateSub": "이미지 1장, 소스 5개",
  "tut.mrcMakeItYours": "나만의 것으로 만들기",
  "tut.mrcClosing1Body": "업로드한 이미지를 내 이미지로 바꾸고 다시 실행하세요. 토큰은 파일이 아니라 위치를 가리키므로 그대로 작동합니다.",
  "tut.mrcClosing2Eyebrow": "결과가 어긋났다면",
  "tut.mrcClosing2Body": "프롬프트를 다시 쓰기 전에 레퍼런스 순서를 확인하세요. 번호가 뜻하는 것은 이름이 아니라 위치입니다.",
  "tut.mrcClosing3Eyebrow": "레퍼런스 하나의 효과를 느끼려면",
  "tut.mrcClosing3Body": "바꾸고, 다시 실행하고, 비교하세요. 한 번에 변수 하나씩, 그것이 방법의 전부입니다.",
  "tut.pnLesson1Title": "“인물” 노드 알아보기",
  "tut.pnLesson1Sub": "선택한 항목이 프롬프트 문장이 됩니다",
  "tut.pnLesson1Body": "속성을 고르면 노드가 캐릭터 프롬프트를 대신 작성합니다. 모델에 정확히 무엇이 전송되는지 보려면 “이미지 생성”에서 “최종 프롬프트”를 여세요.",
  "tut.pnLesson1Callout": "직접 해 보세요. 속성 하나를 바꾸고 프롬프트가 업데이트되는 것을 확인하세요. “프롬프트” 입력란에 입력한 내용은 이 프롬프트와 합쳐집니다.",
  "tut.pnLesson2Title": "같은 노드, 다른 캐릭터",
  "tut.pnLesson2Sub": "선택을 바꾸면 모든 것이 바뀝니다",
  "tut.pnLesson2Body": "같은 “인물” 노드라도 속성이 다르면 완전히 다른 결과가 나옵니다. 1단계에서는 에디토리얼 스트리트 스타일이었지만, 여기서는 같은 노드가 친밀한 분위기의 실내 포트레이트를 만듭니다.",
  "tut.pnLesson3Title": "노드를 쌓아 장면 전체 제어",
  "tut.pnLesson3Sub": "장면, 프레이밍, 분위기, 캐릭터",
  "tut.pnLesson3Body": "같은 “인물” 노드에 이번에는 “배경막”, “프레이밍”, “분위기” 노드를 겹쳤습니다. 각 노드가 자신의 설명을 “최종 프롬프트”에 추가합니다.",
  "tut.pnLesson3Closing": "같은 모델, 완전히 다른 샷. 블록 하나를 바꾸고 다시 실행해 보세요.",
  "tut.pnOrderScene": "장면",
  "tut.pnOrderFraming": "프레이밍",
  "tut.pnOrderMood": "분위기",
  "tut.pnOrderCharacter": "캐릭터",
  "tut.pnRailStep1Sub": "7가지 선택이 하나의 프롬프트 문장이 됩니다",
  "tut.pnRailStep3Title": "노드를 쌓아 장면 제어",
  "tut.pnRailStep3Sub": "그 위에 배경막, 프레이밍, 분위기",
  "tut.pnNoteEyebrow": "기본 패턴",
  "tut.pnNoteBody": "모듈식 블록으로 이미지를 구성하세요. 노드를 바꾸기만 하면 빠르게 다시 시도할 수 있습니다.",
  "tut.iedNavyName": "재킷을 네이비로",
  "tut.iedSubWritten": "글로 쓴 지시",
  "tut.iedNavyWhy": "가장 단순한 편집입니다. 무엇을 바꾸고 무엇을 그대로 둘지 말하면 됩니다. 유지하고 싶은 것을 명시해야 모델이 재킷과 함께 얼굴까지 다시 그리지 않습니다.",
  "tut.iedGoldenName": "골든아워",
  "tut.iedSubLighting": "“조명” 노드로 제어",
  "tut.iedGoldenWhy": "프롬프트가 전혀 없습니다. 선택한 값은 “조명” 노드에 담겨 있고, 편집이 그 값을 읽어 옵니다. 그래서 샷의 조명을 바꾸는 일은 정확히 써야 하는 문장이 아니라 드롭다운 하나로 끝납니다.",
  "tut.iedTealName": "틸 앤 오렌지",
  "tut.iedSubColor": "“색감 / 룩” 노드로 제어",
  "tut.iedTealWhy": "다시 그리는 것이 아니라 색 보정입니다. 같은 이미지에 필름 룩을 적용한 것으로, 프롬프트로는 세 줄을 써도 제대로 설명하기 어려운 종류의 변화입니다.",
  "tut.iedAnimeName": "애니메이션, 회화풍",
  "tut.iedSubTwoStyles": "“스타일” 노드 2개를 동시에 사용",
  "tut.iedAnimeWhy": "“스타일” 노드 2개가 이 편집 하나에 입력되고, 결과에는 두 스타일이 섞입니다. 스타일은 하나만 넣을 수 있는 슬롯이 아닙니다. 겹쳐 쌓으면 어느 하나만으로는 표현할 수 없는 룩이 나옵니다.",
  "tut.iedAtomicName": "아토믹 에이지, 1950년대",
  "tut.iedSubEra": "“시대” 노드로 제어",
  "tut.iedAtomicWhy": "시대는 의상, 색 팔레트, 필름 질감을 한꺼번에 담고 있습니다. 또한 이 편집은 옆의 편집들과 다른 모델로 실행되는데, 모델은 캔버스 전체 설정이 아니라 노드마다 고르는 것입니다.",
  "tut.iedCyberName": "사이버펑크",
  "tut.iedSubStyle": "“스타일” 노드로 제어",
  "tut.iedCyberWhy": "애니메이션풍 편집과 같은 “스타일” 노드를 다른 값으로 설정했습니다. 노드 유형 하나로 카탈로그 전체를 다루므로 다른 룩을 시도하는 것도 클릭 한 번이면 됩니다.",
  "tut.ied85mmName": "85mm 포트레이트",
  "tut.iedSubLens": "“렌즈” 노드로 제어",
  "tut.ied85mmWhy": "내용이 아니라 광학입니다. 초점 거리는 원근 압축과 피사계 심도를 바꿉니다. 피사체는 그대로인데 사진은 전혀 다른 사진이 됩니다.",
  "tut.iedNoBgName": "배경 제거",
  "tut.iedSubNoSettings": "설정 전혀 없음",
  "tut.iedNoBgWhy": "설정할 것도, 쓸 것도 없습니다. 피사체를 투명 배경으로 잘라 내므로 어디에든 바로 올려 쓸 수 있습니다.",
  "tut.iedTokyoName": "밤의 도쿄",
  "tut.iedTokyoWhy": "배경 교체는 두 가지를 동시에 요청합니다. 새 장소, 그리고 그 장소에 맞춘 피사체의 조명입니다. 앞의 것만 요청하면 오려 붙인 티가 납니다.",
  "tut.iedHeadline": "이미지 1장을 넣으면, 서로 다른 편집 9개가 나옵니다.",
  "tut.iedSubline": "모든 편집이 같은 원본을 읽으므로 편집이 쌓이지도, 화질이 떨어지지도 않습니다. 결과를 클릭하면 무엇이 그 결과를 만들었는지 정확히 볼 수 있습니다.",
  "tut.iedChipEdits": "편집 9개",
  "tut.iedChipSharedOriginal": "공통 원본 1장",
  "tut.iedChipNonDestructive": "모두 비파괴 편집",
  "tut.iedInSub": "한 번 생성한 뒤로는 손대지 않음",
  "tut.iedOutSub": "클릭하면 무엇으로 만들었는지 볼 수 있습니다",
  "tut.iedCriticLine": "편집에 비용을 쓰기 전에 원본을 채점합니다.",
  "tut.iedNoSettings": "설정 없음",
  "tut.ccvHeadline": "프레임 1장을 넣으면, 같은 순간을 담은 앵글 10개가 나옵니다.",
  "tut.ccvSubline": "캐릭터, 의상, 장소, 빛은 바뀌지 않습니다. 바뀌는 것은 카메라뿐입니다. 비용을 쓰기 전에 샷 리스트를 확인할 수 있고, 어느 줄이든 다시 쓸 수 있습니다.",
  "tut.ccvChipNodes": "노드 25개가 아닌 6개",
  "tut.ccvChipCuttable": "시퀀스로 편집 가능",
  "tut.countZero": "0",
  "tut.countOne": "1",
  "tut.countTwo": "2",
  "tut.countThree": "3",
  "tut.countFour": "4",
  "tut.countFive": "5",
  "tut.countSix": "6",
  "tut.countSeven": "7",
  "tut.countEight": "8",
