  "tut.ccvInTitle": "레퍼런스 프레임",
  "tut.ccvInSub": "이미지 한 장. 이것이 장면입니다.",
  "tut.ccvRefPromptEyebrow": "레퍼런스 프롬프트",
  "tut.ccvBriefEyebrow": "커버리지 브리프 · 편집하면 계획이 바뀝니다",
  "tut.ccvBriefRule1": "실제 커버리지 순서: 와이드, 미디엄 2개, 클로즈업 2개, 오버 더 숄더, 리버스, 인서트, 다이내믹 앵글, 옆모습.",
  "tut.ccvBriefRule2": "한 줄에 카메라 앵글 하나. 앵글 용어 두 개를 겹쳐 쓰지 마세요.",
  "tut.ccvBriefRule3": "움직임이 아니라 카메라 위치를 지정합니다. 모션은 나중에 추가합니다.",
  "tut.ccvBriefRule4": "화면 방향을 일관되게 유지해 컷이 튀지 않게 합니다.",
  "tut.ccvBriefRule5": "여백을 남기세요. 모든 프레임이 애니메이션의 시작 프레임으로 쓰일 수 있어야 합니다.",
  "tut.ccvListTitle": "샷 리스트",
