  "tut.ccvNotRun": "아직 실행 안 됨",
  "tut.referenceN": "레퍼런스 {n}",
  "tut.recipeN": "레시피 {n}",
  "tut.editN": "편집 {n}",
  "tut.coverageShot": "커버리지 샷",
  "tut.promptEyebrow": "프롬프트",
  "tut.ocHeadline": "이미지 2장. 레시피 5개. 마스크도 레이어도 없습니다.",
  "tut.ocSubline": "아래의 모든 레시피는 같은 소스 두 개를 읽습니다. 달라지는 것은 각 소스의 어느 부분을 지정하는지, 그리고 몇 번으로 지정하는지뿐입니다. 이것이 기법의 전부입니다.",
  "tut.ocChipNoMask": "마스크 없음",
  "tut.ocInTitle": "소스 이미지 2장",
  "tut.ocInSub": "1장은 생성, 1장은 업로드",
  "tut.ocRoleGenerated": "생성한 런웨이 사진",
  "tut.ocRoleUploaded": "업로드한 스튜디오 사진",
  "tut.ocSameTwoEyebrow": "매번 같은 두 장",
  "tut.ocSameTwoBody": "레시피 5개 모두 이 두 이미지에 연결되어 있습니다. 실행 사이에 다시 업로드하거나 편집하는 것은 없습니다.",
  "tut.ocRecipesTitle": "레시피 5개",
  "tut.ocRecipesSub": "각각 프롬프트 한 줄",
  "tut.ocRecipesMeta": "하나를 클릭하세요",
  "tut.ocTakesEyebrow": "이 레시피가 가져오는 것",
  "tut.ocNodeEyebrow": "노드",
  "tut.ocR1Name": "얼굴은 한쪽에서, 몸은 다른 쪽에서",
  "tut.ocR1OutTitle": "한 사람의 몸, 다른 사람의 얼굴",
  "tut.ocR1OutSub": "레시피 1 · 두 레퍼런스 모두 수식어 지정",
  "tut.ocR1LessonKind": "기본형",
  "tut.ocR1Lesson": "수식어를 붙인 레퍼런스 두 개로 이미지 두 장에서 한 사람을 만듭니다. 어느 이미지도 통째로 들어오지 않습니다.",
  "tut.ocR1Note1": "포즈, 체격, 프레이밍. 얼굴은 사용하지 않습니다.",
  "tut.ocR1Note2": "얼굴만 넘어옵니다.",
  "tut.ocR2Name": "순서를 바꾸면 결과도 바뀝니다",
  "tut.ocR2OutTitle": "같은 레시피, 반대로",
  "tut.ocR2OutSub": "레시피 2 · 번호 교환",
  "tut.ocR2LessonKind": "이 템플릿의 핵심",
  "tut.ocR2Lesson": "수식어는 같고 번호만 바꿨습니다. 어느 이미지가 1이고 어느 이미지가 2인지에 따라 결과 이미지에 누가 나오는지가 정해집니다.",
  "tut.ocR2Note1": "이번에는 두 번째 소스가 몸을 제공합니다.",
  "tut.ocR2Note2": "그리고 첫 번째 소스는 얼굴만 제공합니다.",
  "tut.ocR3Name": "무대는 그대로, 주인공만 교체",
  "tut.ocR3OutTitle": "같은 장소, 다른 인물",
  "tut.ocR3OutSub": "레시피 3 · background 수식어",
  "tut.ocR3LessonKind": "다른 수식어",
  "tut.ocR3Lesson": "“background”는 그 자리에 있던 인물을 뺀 장소만 요청합니다. 남기고 싶은 것이 장소일 때 유용합니다.",
  "tut.ocR3Note1": "모델을 뺀 런웨이와 그 조명.",
  "tut.ocR3Note2": "이제 그곳에 서는 인물.",
  "tut.ocR4Name": "런웨이에서 스튜디오로",
  "tut.ocR4OutTitle": "같은 인물, 다른 장소",
  "tut.ocR4OutSub": "레시피 4 · 레시피 3의 반대",
  "tut.ocR4LessonKind": "전치사에 주목",
  "tut.ocR4Lesson": "“settings”는 위 레시피의 반대입니다. 인물은 그대로 두고 다른 곳으로 옮깁니다. 배치를 정하는 것은 “in”이라는 단어입니다.",
  "tut.ocR4Note1": "피사체를 통째로 옮깁니다.",
