  "tut.regWdStep5Sub": "동영상과 음성 병합",
  "tut.regPnTitle": "“인물” 노드 시작하기",
  "tut.regPnSummary": "드롭다운에서 속성을 고르면 노드가 캐릭터 프롬프트를 대신 작성합니다. 노드 하나에서 시작해 전체 스택까지, 실행 3회로 살펴봅니다.",
  "tut.regPnChip": "실행 3회",
  "tut.regSunoTitle": "노드로 음악 만들기",
  "tut.regSunoSummary": "곡 설명을 직접 쓰지 않습니다. 옵션을 고르면 노드가 대신 작성합니다.",
  "tut.regSunoChip": "실행 7회",
  "tut.regSunoNoteEyebrow": "이 튜토리얼 사용법",
  "tut.regSunoNoteBody": "실행을 하나씩 넘겨 보세요. 각 실행은 바로 앞 실행에서 정확히 한 가지만 바꾸므로, 들리는 차이는 바뀐 옵션 때문입니다.",
  "tut.regSunoStep1Title": "스타일 노드에서 옵션 선택",
  "tut.regSunoStep1Sub": "장르, 분위기, 악기 구성, 보이스",
  "tut.regSunoStep2Title": "“Suno 생성”으로 전달",
  "tut.regSunoStep2Sub": "선택한 옵션이 스타일 설명이 됩니다",
  "tut.regSunoStep3Title": "완성된 트랙 받기",
  "tut.regSunoStep3Sub": "재생한 다음 옵션 하나를 바꿔 보세요",
  "tut.regApTitle": "SNS 오토파일럿",
  "tut.regApSummary": "아이디어를 붙여 넣으세요. 노드 7개가 슬라이드로 나누고, 슬라이드마다 이미지를 그리고, 캡션을 쓴 다음 게시합니다.",
  "tut.regApStep1Title": "텍스트 한 덩어리 입력",
  "tut.regApStep1Sub": "그 밖에 입력할 것은 없습니다",
  "tut.regApStep2Title": "슬라이드 10장 작성 및 그리기",
  "tut.regApStep2Sub": "슬라이드별 문구와 이미지",
  "tut.regApStep3Title": "캡션 작성 및 게시",
  "tut.regApStep3Sub": "피드에 맞게 형식을 맞춘 뒤 게시",
  "tut.regIedTitle": "이미지 편집 시작하기",
  "tut.regIedSummary": "이미지를 한 번 생성하고, 독립된 편집 9개가 각각 같은 원본을 읽습니다. 편집이 쌓이지 않으므로 화질도 떨어지지 않습니다.",
  "tut.regIedNoteEyebrow": "체인이 아니라 분기입니다",
  "tut.regIedNoteBody": "모든 편집이 원본을 직접 읽습니다. 하나를 바꿔도 나머지 8개는 영향을 받지 않습니다. 이것이 핵심입니다.",
  "tut.regIedStep1Sub": "한 번 생성한 뒤 채점",
  "tut.regIedStep2Title": "편집 9개, 소스 하나",
  "tut.regIedStep2Sub": "모두 같은 이미지를 읽습니다",
  "tut.regIedStep3Title": "결과 따라가기",
  "tut.regIedStep3Sub": "타일을 클릭하면 무엇으로 만들었는지 볼 수 있습니다",
  "tut.regCcvTitle": "카메라 커버리지 — 프레임 1장, 앵글 10개",
  "tut.regCcvSummary": "레퍼런스 프레임 1장을 넣으면 같은 장면의 샷 10개가 나옵니다. 바뀌는 것은 카메라뿐입니다. 이미지 한 장으로, 바로 편집해 이어 붙일 수 있는 감독의 커버리지 플랜을 얻습니다.",
  "tut.regCcvChip": "샷 10개",
  "tut.regCcvNoteEyebrow": "핵심은 리스트입니다",
  "tut.regCcvNoteBody": "이미지 노드 1개, 행 10개. 리스트가 분기시키므로 샷 10개에 필요한 노드는 25개가 아니라 6개입니다. 또한 한 줄을 편집하면 그 앵글 하나만 다시 촬영합니다.",
  "tut.regCcvStep1Sub": "이미지 1장과 계획을 좌우하는 브리프",
  "tut.regCcvStep2Sub": "비용을 쓰기 전에 읽고 다시 쓸 수 있는 10줄",
  "tut.regCcvStep3Sub": "이미지 노드 하나로 만든, 한 순간의 샷 10개",
  "tut.regOcTitle": "캐릭터 하나, 어떤 장면이든",
  "tut.regOcSummary": "소스 이미지 2장, 한 줄짜리 레시피 5개, 마스크도 레이어도 없습니다. 결과마다 달라지는 것은 각 소스의 어느 부분을 지정하는지, 그리고 몇 번으로 지정하는지입니다.",
  "tut.regOcChip": "레시피 5개",
  "tut.regOcNoteEyebrow": "그림이 아니라 번호를 보세요",
  "tut.regOcNoteBody": "{image:1} 및 {image:2} 표기는 노드 이름이 아니라 “레퍼런스” 목록의 위치(소스를 연결한 순서)를 나타냅니다. 레시피 2는 레시피 1에서 번호만 바꾼 것이며, 이것이 이번 레슨의 전부입니다.",
  "tut.regOcStep1Sub": "1장은 생성, 1장은 업로드 — {image:1} 및 {image:2}",
  "tut.regOcStep2Sub": "하나를 클릭하면 각 소스에서 가져오는 것과 이 레시피가 알려 주는 내용을 볼 수 있습니다",
  "tut.regOcStep3Sub": "결과 이미지와, 가져온 부분들이 어떻게 합쳐지는지",
  "tut.regUwTitle": "바닷속 거인들",
  "tut.regUwSummary": "장면 8개를 쓰세요. 각 장면이 이미지가 되고, 다시 5초짜리 샷이 되어 음악과 함께 편집된 뒤 릴스로 게시됩니다.",
  "tut.regUwStep1Title": "장면 8개 쓰기",
